SELECT ?s ?p ?o WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  FILTER(?lbl = "Core_top")
}

SELECT ?z ?cls ?lbl WHERE {
  ?z a ?cls .
  ?z rdfs:label ?lbl .
  FILTER(STRSTARTS(?lbl, "Core_top ZN") || STRSTARTS(?lbl, "Core_top"))
}

SELECT ?sensor ?lbl ?tsid WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:hasPropertyOf ?zone .
  ?zone rdfs:label ?lbl .
  FILTER(?zone = http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z01)
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?lbl ?tsid WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:hasPropertyOf http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z01 .
  ?sensor rdfs:label ?lbl .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?tsref WHERE {
  ?sensor ref:hasExternalReference ?tsref .
  FILTER(strstarts(str(?tsref), "urn:buildgraph:tsref:"))
  ?sensor rdfs:label ?lbl .
} LIMIT 30

SELECT ?sensor ?cls ?lbl ?tsref WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor rdfs:label ?lbl .
  ?sensor ref:hasExternalReference ?tsref .
  FILTER(CONTAINS(str(?tsref), "urn:buildgraph:tsref"))
}

SELECT ?sensor ?lbl ?target WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor rdfs:label ?lbl .
  OPTIONAL { ?sensor brick:pointOf ?target }
  OPTIONAL { ?sensor brick:hasPropertyOf ?target }
}

